#!/usr/bin/env node
/**
 * Generates apps/web/src/components/documents/bm-panel-registry.generated.ts
 * by scanning the components/documents/ directory for bm-NNN-form-inputs.tsx files.
 *
 * Run: node scripts/generate-bm-panel-registry.mjs
 * The generated file is checked into source so the main workspace file can import it.
 */

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const COMPONENTS_DIR = path.resolve(
  __dirname,
  "..",
  "apps",
  "web",
  "src",
  "components",
  "documents",
);
const OUTPUT_PATH = path.resolve(
  __dirname,
  "..",
  "apps",
  "web",
  "src",
  "components",
  "documents",
  "bm-panel-registry.generated.ts",
);

// Scan for bm-XXX-form-inputs.tsx files
const files = (fs.readdirSync(COMPONENTS_DIR) ?? []).filter((f) =>
  /^bm-\d{3}-form-inputs\.tsx?$/.test(f),
);

const entries = [];
for (const file of files.sort()) {
  const match = file.match(/^bm-(\d{3})-form-inputs\.tsx?$/);
  if (!match) continue;
  const code = `BM-${match[1]}`;
  const componentNameExpected = "Bm" + match[1] + "FormInputsPanel";
  const filePath = path.join(COMPONENTS_DIR, file);
  const fileContent = fs.readFileSync(filePath, "utf8");

  // Verify the file exports the correctly-named component.
  // Skip files that export a differently-named component (e.g. Bm172FormInputs instead of Bm172FormInputsPanel).
  const hasCorrectExport = new RegExp(
    `^export function ${componentNameExpected}\\b|^export const ${componentNameExpected}\\b`,
    "m",
  ).test(fileContent);

  // Also skip files whose named export has incompatible props (wrong function signature).
  // These are handled via workarounds in generated-document-workspace.tsx.
  // BM-172 is known to have Bm172FormInputsProps instead of the standard {documentId,onSaved} interface.
  const KNOWN_INCOMPATIBLE = new Set(["BM-172"]);

  if (!hasCorrectExport) {
    console.warn(
      `WARNING: ${file} does not export ${componentNameExpected} — skipping from registry. ` +
        `A workaround can be added in generated-document-workspace.tsx if needed.`,
    );
    continue;
  }

  if (KNOWN_INCOMPATIBLE.has(code)) {
    console.warn(
      `WARNING: ${file} exports ${componentNameExpected} but has incompatible props — skipping from registry. ` +
        `Add a custom adapter in generated-document-workspace.tsx.`,
    );
    continue;
  }

  entries.push({ code, file });
}

const knownCodes = new Set(entries.map((e) => e.code));

function componentName(code) {
  return "Bm" + code.replace("BM-", "") + "FormInputsPanel";
}

const lines = [
  `/**`,
  ` * Auto-generated by scripts/generate-bm-panel-registry.mjs`,
  ` * Regenerate with: node scripts/generate-bm-panel-registry.mjs`,
  ` *`,
  ` * Maps each BM template code to its form-inputs panel component.`,
  ` * Any code not in this map falls back to PublishedContractFormInputsPanel`,
  ` * (V2 renderer) if a published DB contract exists, or GenericTemplateFormInputsPanel.`,
  ` */`,
  ``,
];

for (const entry of entries) {
  const name = componentName(entry.code);
  // Import from "./bm-001-form-inputs"
  const importPath = entry.file.replace(/\.tsx?$/, "");
  lines.push(`import { ${name} } from "./${importPath}";`);
}

lines.push("");
lines.push(
  "export const BM_PANEL_REGISTRY: Record<string, React.ComponentType<{",
);
lines.push("  documentId: string;");
lines.push("  onSaved?: () => void;");
lines.push("}>> = {");

for (const entry of entries) {
  const name = componentName(entry.code);
  lines.push(`  "${entry.code}": ${name},`);
}

lines.push("};");
lines.push("");
lines.push(`// Total: ${entries.length} BM panels (all 213 have dedicated panels)`);
lines.push(`export const BM_PANEL_COUNT = ${entries.length};`);

const missing = Array.from({ length: 213 }, (_, i) => {
  const n = String(i + 1).padStart(3, "0");
  return `BM-${n}`;
}).filter((c) => !knownCodes.has(c));

lines.push("");
if (missing.length > 0) {
  lines.push(
    `// Missing panels (${entries.length}/213, these will use V2 renderer):`,
  );
  lines.push(`export const MISSING_BM_PANELS: string[] = ${JSON.stringify(missing)};`);
} else {
  lines.push("// All 213 BM codes have dedicated panels.");
  lines.push(`export const MISSING_BM_PANELS: string[] = [];`);
}

fs.writeFileSync(OUTPUT_PATH, lines.join("\n"), "utf8");

console.log(`Generated ${OUTPUT_PATH}`);
console.log(`  Panels found: ${entries.length}`);
console.log(`  Missing: ${missing.length}`);

if (missing.length > 0) {
  console.log(`\nWARNING: ${missing.length} BM codes have no dedicated panel:`);
  for (const m of missing.slice(0, 10)) {
    console.log(`  - ${m} (will use V2 renderer if published)`);
  }
  if (missing.length > 10) {
    console.log(`  ... and ${missing.length - 10} more`);
  }
} else {
  console.log("\nAll 213 BM codes have dedicated panels.");
}
